contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function. Takes a candidate new owner to pass to setOwner.
    function run(address candidate) public payable {
        require(candidate != address(0));

        // Read initial owner (view only)
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // Attempt the state-changing call as a top-level statement and capture whether it reverted and its return value.
        bool callReverted;
        bool returnedTrue = false;
        bool ok = c.setOwner(candidate); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            callReverted = true;
        } else {
            callReverted = false;
            returnedTrue = ok;
        }

        // Read owner after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // General rule:
        // - If the call did not revert, it must have returned true and the owner must equal the candidate.
        // - If the call reverted, the owner must be unchanged.
        assert((!callReverted && returnedTrue && ownerAfter == candidate) || (callReverted && ownerAfter == ownerBefore));
    }

    receive() external payable { }
}

